import numpy as np
from scipy.ndimage import label, center_of_mass
A=np.load('source_pixels.npz')['rgb']
for i in range(96):
 a=A[i].astype(int); R,G,B=np.moveaxis(a,-1,0)
 masks={
 'r':(R>120)&(R>G*1.35)&(R>B*1.25),
 'b':(B>65)&(B>R*1.25)&(B>G*1.03),
 'y':(R>100)&(G>80)&(R>B*1.5)&(G>B*1.35)&(R/G<1.8),
 }
 vals=[]
 for k,m in masks.items():
  lab,n=label(m)
  comps=[]
  for j in range(1,n+1):
   ys,xs=np.where(lab==j); s=len(xs)
   if s>=10: comps.append((s,round(xs.mean(),1),round(ys.mean(),1)))
  vals.append(k+':'+str(sorted(comps,reverse=True)[:2]))
 if i%2==0 or i<10: print(f'{i+1:02}',*vals)
